#!/usr/bin/env bash
# HPLIP hpcups (HP inkjets and lasers) as libfpo_hplip.so + data (PPDs are generated by build-hplip-data.sh).
set -euo pipefail
. "$(dirname "$0")/env.sh" "${1:-arm64-v8a}"
bash "$HERE/build-cups.sh" "$ABI" >/dev/null
bash "$HERE/build-libjpeg.sh" "$ABI" >/dev/null

SRC="$WORK/hplip"
if [ ! -d "$SRC/prnt" ]; then extract "$SOURCES/hplip-3.25.6.tar.gz" "$SRC" ${HPLIP_PATCH:-}; fi
cd "$SRC"
# prnt/hpcups/Utils.h and common/utils.h differ only by case; make the include unambiguous on case-insensitive hosts
grep -rl '#include "utils.h"' prnt/hpcups common | xargs -r sed -i 's#"utils.h"#"common/utils.h"#' || true
INC="-I. -Icommon -Iio/hpmud -Iprnt/hpcups -I$OUT/include -I$OUT/jpeg-include"
OBJS=""
for f in $(cat "$HERE/hpcups-sources.txt"); do
  o="$WORK/hplip-$(echo "$f" | tr '/' '_').o"
  case "$f" in
    *.cpp) EXTRA=""; [ "$f" = prnt/hpcups/HPCupsFilter.cpp ] && EXTRA="-Dmain=fpo_filter_main"
           $CXX -std=gnu++14 -O2 -w -fPIC -fvisibility=hidden -DAPDK_LITTLE_ENDIAN -DCONFDIR=\"/etc/hp\" $EXTRA $INC -c "$f" -o "$o" ;;
    *.c)   $CC -O2 -w -fPIC -fvisibility=hidden -fcommon -DAPDK_LITTLE_ENDIAN -DCONFDIR=\"/etc/hp\" $INC -c "$f" -o "$o" ;;
  esac
  OBJS="$OBJS $o"
done
$CXX -x c++ -O2 -fPIC -c "$HERE/shim/fpo_entry.c" -o "$WORK/fpo_entry.o"
$CC -O2 -fPIC -c "$HERE/shim/imageprocessor_stub.c" $INC -o "$WORK/ip_stub.o"
$CXX -shared -o "$OUT/libfpo_hplip.so" $OBJS "$WORK/fpo_entry.o" "$WORK/ip_stub.o" \
  "$OUT/libcups.a" "$OUT/libjpeg.a" -static-libstdc++ -lz -lm -llog -ldl \
  -Wl,--version-script="$HERE/shim/exports.map" -Wl,--gc-sections -Wl,--no-undefined
$STRIP --strip-unneeded "$OUT/libfpo_hplip.so"
ls -la "$OUT/libfpo_hplip.so"
